import {t,lab} from './authoring.mjs';
const source=name=>[[`Microsoft ${name} help and learning`,`https://support.microsoft.com/${name.toLowerCase()}`]];
export default [
{key:'office-1',subject:'Introduction to MS Office',slug:'dit-computer-science',book:'MS Office',module:1,chapter:2,title:'Introduction to Office Automation Software',legacyNoteId:'note-1793112803271',pages:'12',reuseMcqs:20,sources:[...source('Word'),['Office 2016 lifecycle','https://learn.microsoft.com/en-us/lifecycle/products/microsoft-office-2016']],topics:[
t('1.1','Office automation, open-source and proprietary software',`Office automation uses software and connected processes to carry out tasks such as writing correspondence, calculating marks, storing structured records and presenting information. Benefits can include reusable templates, reduced repetitive work, easier revision and more consistent calculations. Incorrect input, a flawed formula or an inappropriate permission can also spread mistakes quickly; automation is not a guarantee of accuracy.

Open-source software is made available under a licence that grants specified rights to inspect, modify and redistribute its source. 'Open source' is a licensing concept, not simply a statement that a download costs nothing. Proprietary software is controlled under its owner's licence and may have paid or no-cost offerings. Follow the actual licence rather than assuming that every free program is open source or every proprietary product requires the same payment model.

Choose a tool by the task, required formats, collaboration environment, accessibility and authorised licence. A document export should be checked on the intended viewer, particularly when layout, fonts or macros matter. Keep editable source files and an appropriate backup rather than treating a PDF or shortcut as a universal replacement.`,[]),
t('1.2','The Office 2016 suite and application roles',`The syllabus edition is Microsoft Office 2016. Word supports document editing and page layout; Excel supports worksheets and calculations; PowerPoint supports slide presentations; Access supports small relational-database applications in its supported desktop environment. The programs exchange some data, but their primary objects and tasks differ.

Choose Word for a letter, Excel for a marks calculation, PowerPoint for a short class presentation and Access for related student/course tables. A document table is not automatically a relational database, and a spreadsheet cell is not the same as a PowerPoint text box.

Office 2016 reached end of support on 14 October 2025. Study its interface in the authorised syllabus lab, and consult the vendor's current support information for real deployment decisions. Later product editions can add features that perpetual Office 2016 does not have. A feature demonstration should identify the actual edition rather than silently claiming every menu is available everywhere.`,[]),
t('1.3','Common interface components and file workflow',`The title bar identifies the application/document window. The Quick Access Toolbar exposes selected frequent commands. The Ribbon groups commands into tabs and groups; contextual tabs can appear when an object such as a table or picture is selected. A dialog-box launcher opens additional settings for its group. The document page, worksheet grid, slide workspace or database object view is the application's working area. The status bar presents contextual information such as page/word counts or view/zoom controls.

The syllabus repeats the Quick Access Toolbar entry; it is one interface concept, not two distinct components. Distinguish application zoom from changing a document's actual font or printed page size. File/Backstage operations include new, open, save, export and print.

Create a new sample, save it with a meaningful name in an authorised folder, close it and reopen the intended copy. Save As can create a different named copy or format. Export to PDF for a fixed-layout deliverable where appropriate, then reopen the PDF and verify pages and content. Keep the editable document and any required linked assets. File extension changes alone do not convert data formats.`,[])
],short:[['What is office automation?','Using software and organised workflows for tasks such as documents, calculations, records and presentations, with appropriate verification.'],['Does free of charge mean open source?','No. Price and source-code licensing rights are different properties.'],['Which application suits a marks formula?','Excel, because its worksheets and formulas support tabular calculation.'],['What is a contextual Ribbon tab?','A tab relevant to a selected object, such as table tools appearing when a table is selected.'],['What is application zoom?','A viewing magnification setting; it does not by itself change the stored font size or paper size.'],['Why retain the editable source after PDF export?','It preserves the practical editing workflow and source structure. A PDF is useful for distribution but is not a universal substitute for the original file.']],long:[['Select Office tools for a small institute.','Use Word for correspondence and handouts, Excel for a checked marks sheet, PowerPoint for a presentation and Access where related structured tables and queries are required. State the expected input, output format and audience for each task. Use authorised licensing, meaningful filenames and an appropriate backup. Test a calculation with independent expected values, reopen exported documents and verify that linked media or fonts remain available. Tool choice and automation do not replace data validation.'],['Explain the common Office interface.','The title bar identifies the current context; the Quick Access Toolbar exposes chosen frequent commands; Ribbon tabs contain groups of related actions; a dialog launcher opens further options. Contextual tabs depend on a selected object. The main work area reflects the application, while the status bar and view/zoom controls report or adjust the current view. File/Backstage supports file-level operations. The same general pattern does not mean a worksheet and a document page are identical objects.'],['Explain a checked document-delivery workflow.','Create the required editable source in an authorised location, apply meaningful naming and save it. Reopen the correct file to verify persistence. Export to the requested distribution format and inspect the exported pages/content using an appropriate viewer. Retain source data and linked assets where required. A renamed extension does not perform a real conversion, and a successful save dialog alone does not show that the intended content or layout is correct.']],labs:[lab('office1-interface','Identify application-specific and shared interface parts',['Open an authorised Word, Excel, PowerPoint or Access training file.','Label title bar, Quick Access Toolbar, Ribbon tabs/groups, work area and status bar.','Select an object and identify any contextual tab; save and reopen a harmless sample.'],'A labelled interface sheet and a reopened sample.',{practicals:[1]})]
},
{key:'office-2',subject:'Introduction to MS Office',slug:'dit-computer-science',book:'MS Office',module:2,chapter:3,title:'Microsoft Word',legacyNoteId:'note-1793115340417',pages:'12,14-15',reuseMcqs:20,sources:source('Word'),topics:[
t('2.1','Word-processing features and document structure',`A word processor combines text editing with formatting, page layout and output controls. Editing changes content; character formatting changes properties such as font, size and emphasis; paragraph formatting changes alignment, indentation and spacing; page settings determine paper, margins and orientation.

Use headings/styles to express structure rather than making every heading a manually enlarged paragraph. Headers and footers repeat information in their section context. Pictures and tables add objects that can require their own layout controls. Spelling and grammar tools suggest potential corrections, but names, specialist terms and meaning still need human review.

Views serve different purposes. Print Layout helps inspect page arrangement; other views can support drafting or navigation. Zoom changes the view, not the actual type size. Before distribution, inspect both screen layout and the intended print/PDF output.`,[]),
t('2.2','Create, save, edit, find and print',`Create a blank document or a suitable template. A template supplies a starting structure; replace sample content and verify that it fits the actual task. Save the editable document with a meaningful name, normally .docx for an ordinary Word 2016 document without macros. Save As or export can create PDF or other required formats, with possible feature/layout differences that must be checked.

Use selection carefully before cut, copy or paste. Cut removes selected content for movement; copy retains the source. Paste choices affect whether original formatting is retained, merged or reduced to text. Undo helps recover a mistaken local edit; it is not a replacement for a long-term backup.

Find locates a term; Replace can change matches. Preview replacements, especially Replace All, because a substring can occur in unintended contexts. AutoCorrect applies configured substitutions and is different from a proofing suggestion. Use the print preview to choose the correct printer, page range, copies and layout before a training print. Saving the file and printing a page are different operations.`,[]),
t('2.3','Fonts, character attributes, styles and WordArt',`The Font group controls font family, size, bold/italic/underline, colour and other character attributes. Superscript raises characters such as an exponent; subscript lowers them, as in a chemical label. Font-dialog advanced settings can change character spacing. Avoid using repeated spaces as a general page-layout tool.

Format Painter transfers formatting from a selected source to another target; it does not copy the source wording. Styles store named sets of formatting and support consistent headings/body text. Clear Formatting removes applicable direct formatting but should be checked against the intended style and selection.

WordArt is a decorative text object with visual effects. It should not replace readable body text or a meaningful heading structure. Inspect objects after editing and export, because wrapping, fonts and page dimensions can change the perceived result.`,[]),
t('2.4','Paragraph formatting and lists',`Paragraph alignment controls placement relative to the available line width. Left/right indents move the paragraph edges; a first-line indent shifts the first line, and a hanging indent shifts following lines relative to the first. Set these using paragraph controls rather than inserting a long run of spaces.

Line spacing controls space between lines within a paragraph; before/after spacing controls separation between paragraphs. A blank paragraph inserted repeatedly is not the same setting and can create inconsistent pagination.

Bulleted lists identify unordered items, while numbered lists show an ordered sequence. Use list levels for meaningful sublists and inspect numbering when items are inserted, moved or deleted. List indentation and text indentation interact, so verify the result with the actual selected paragraphs.`,[]),
t('2.5','Page setup, breaks, columns and printing',`Margins define the writable page area. Paper size and portrait/landscape orientation should match the intended output. Columns divide a text flow; they are not the same as cells in a table. Page breaks move subsequent content to another page without requiring repeated empty lines.

A section break permits section-specific formatting such as a landscape page inside an otherwise portrait document or different headers/footers. A page break alone does not create a separate formatting section. When editing headers/footers, check any Link to Previous relationship before assuming a change is confined to one section.

Choose the intended printer or PDF export, inspect page count, scaling, range and number of copies, and review the actual output. A practical report should state the chosen paper/orientation/margins and explain where a page or section break was required.`,[]),
t('2.6','Tables, AutoFit and cell structure',`Insert a table with the specified row and column count, add meaningful headings and place values in the intended cells. Row height and column width affect readability. AutoFit can fit contents or the available width, depending on the chosen option; it does not guarantee that every long entry will remain on one printed line.

Table Tools provide layout actions such as resizing, inserting/deleting rows/columns and merging/splitting cells. Merging combines selected cells into a larger cell; splitting creates a specified smaller cell arrangement. Check whether a changed structure still represents the data clearly.

For the 3-by-5 exercise, explicitly record whether the instruction means three columns and five rows, and follow the instructor's stated convention. A table in a Word document is a layout/data object, not automatically a relational table with enforced database keys. Inspect table borders, wrapping and page breaks in the exported/printed version.`,[]),
t('2.7','Urdu input, fonts and paragraph direction',`Urdu document work requires suitable character input, a Unicode-capable font and appropriate right-to-left paragraph direction. Adding a Windows Urdu keyboard changes how keys produce characters; setting Word's paragraph direction changes how the paragraph flows. These are separate controls.

Use the authorised Windows language/input settings and test the selected keyboard layout. The syllabus also mentions a Pak-Urdu installer for older Windows systems; that is a version-specific historical route, not proof that every current Windows installation needs a third-party installer. Obtain any required tool only through the lab's approved source.

Type a short Urdu sample, apply an available supporting typeface such as the specified Arabic/Urdu Typesetting family where installed, and inspect mixed English/Urdu punctuation, numbers and alignment. Save and reopen the .docx, export to PDF and inspect the glyph joining and reading direction. A string of visible Arabic-script characters can still be wrong if its joining or direction is broken.`,[])
],short:[['Editing versus formatting?','Editing changes wording/data. Formatting changes presentation properties such as type, paragraph layout and page setup.'],['What does Format Painter copy?','Formatting attributes from the chosen source, rather than the source text itself.'],['Compare a first-line and hanging indent.','A first-line indent offsets the first line. A hanging indent offsets following lines relative to the first.'],['Why use section breaks?','They permit section-specific layout such as a landscape page or different header/footer settings.'],['What should be checked after a table merge?','The data structure, headings, row/column layout and printed/PDF readability.'],['Which three concerns support Urdu typing?','Input layout, glyph-supporting font and correct paragraph direction.']],long:[['Prepare a structured bilingual assignment.','Create a document with a title, meaningful heading styles, body paragraphs and an appropriate table. Set the required paper, margins and paragraph spacing. Enter English and Urdu using suitable input layouts, Unicode fonts and directions, checking punctuation and mixed numbers. Add the requested header/footer and use page or section breaks according to layout needs. Save the editable document, reopen it, export a PDF and inspect pages, table structure and joined Urdu text.'],['Explain paragraph and page formatting using a report.','Use paragraph controls for alignment, first-line/hanging/left/right indents and line/before/after spacing. Use page controls for margins, size, orientation and columns. Insert a page break when content should start on another page, and a section break when subsequent formatting must differ. Avoid constructing layout from repeated spaces and blank paragraphs. Check headers/footers for section links and inspect print/PDF output rather than relying solely on the editor view.'],['Explain a checked Word table exercise.','State the required row/column convention, create the table and enter headings and sample data. Adjust widths/heights or AutoFit deliberately. Merge or split selected cells as requested and check that the resulting structure still communicates the intended data. Apply readable borders/alignment and inspect pagination. Reopen the saved source and exported PDF. A document table helps present information but does not by itself enforce relational-database identities or relationships.']],labs:[
lab('word-edit','Create, save and edit a report',['Identify Ribbon groups and create a blank document through File/New or the equivalent toolbar command.','Save a uniquely named .docx in a practice folder; reopen it and add content.','Create a second document from a suitable template, replace sample text and inspect print preview.','Export a PDF, reopen it and compare its content.'],'Editable and exported files with verified names/content.',{practicals:[2,3,4,5,6,7]}),
lab('word-character','Apply and compare character formatting',['Use a selected passage to test font, size, colour, bold, superscript and subscript.','Change character spacing through the Font dialog and inspect the difference.','Use Format Painter on a second passage, then Clear Formatting on a selected sample.'],'A comparison explaining which attributes changed and which wording did not.',{practicals:[8,9,10]}),
lab('word-paragraph','Structure paragraphs and lists',['Apply first-line, hanging, left and right indents to labelled sample paragraphs.','Set line spacing and before/after spacing using the actual controls.','Convert sample items into bullets, numbered steps and a meaningful sublist.'],'Consistent paragraphs and lists without repeated-space layout.',{practicals:[11,12,13]}),
lab('word-layout','Create a mixed-layout document',['Choose the assigned paper size and margins.','Make one section landscape using a section break and contrast it with a simple page break.','Inspect headers/footers and choose the intended printer, page range and copies in preview.'],'A checked multi-page layout and a justified break choice.',{practicals:[14,15,16,17]}),
lab('word-table','Create and reshape a training table',['Create the requested 3-by-5 table using the stated row/column convention.','Enter headings/data, adjust dimensions and AutoFit deliberately.','Merge and split selected cells; inspect structure and PDF pagination.'],'A readable correctly structured table.',{practicals:[18,19]}),
lab('word-urdu','Produce a verified Urdu sample',['Add the approved Urdu keyboard/layout and choose a supporting installed font.','Set the intended right-to-left paragraph direction, including a mixed-language sample.','Save, reopen and inspect the exported PDF for direction and joined glyphs.'],'Legible editable and PDF Urdu text.',{practicals:[20]})]
},
{key:'office-3',subject:'Introduction to MS Office',slug:'dit-computer-science',book:'MS Office',module:3,chapter:11,title:'Microsoft Excel',legacyNoteId:'dit-nov11-excel-mcq-notes',pages:'12-13,15-17',reuseMcqs:20,sources:source('Excel'),topics:[
t('3.1-3.2','Workbooks, worksheets and data entry',`A workbook is the saved Excel file, normally .xlsx for an ordinary workbook without VBA. It contains worksheets; a worksheet has rows, columns and cells. A1 identifies column A, row 1. A range such as B2:F2 includes several cells. The Name Box identifies a selected reference or name, and the formula bar shows/edits the active cell's content or formula.

Enter values in the intended types. A phone number is often an identifier better stored as text, not a quantity to add. Dates have a stored representation and a display format; an ambiguous typed date can be interpreted according to locale. Inspect the actual result and choose a clear format.

Clearing contents is different from deleting a cell, row or column. Deletion can shift other cells and affect references. Cut/copy/paste choices determine whether values, formulas or formatting move. The number of default worksheets can depend on settings; if the task needs three, create and name them explicitly instead of assuming every installation starts with three. Save, reopen and verify the intended workbook, and inspect a PDF export separately.`,[]),
t('3.3','Formatting cells, sheets and printed output',`Cell formatting changes appearance, not automatically the underlying value. Percentage formatting can display 0.75 as 75%; multiplying a value by 100 is a separate calculation. Use appropriate number formats for marks, currency or dates and inspect the formula bar when a display is ambiguous.

Insert/delete rows and columns deliberately, use Format Painter for presentation attributes, and give worksheets meaningful names. The fill handle can copy formulas or extend recognised series, so inspect what was actually filled. Merging cells can complicate tabular data and sorting; use it for an appropriate title area rather than casually merging a data table.

Headers/footers belong to printed page layout. Zoom changes screen magnification. Print Selection, Active Sheets and Entire Workbook have different scopes. Check page orientation, print area, scaling, repeated headers where needed and the actual preview so a marks column does not disappear onto an unexpected extra page.`,[]),
t('3.4a','Formulas, operators and relative/absolute/mixed references',`An Excel formula starts with =. Arithmetic follows precedence, with parentheses making intended grouping explicit. =2+3*4 returns 14, while =(2+3)*4 returns 20. Relative references adjust when a formula is copied. Absolute references lock row and column, such as $J$2. Mixed references lock one dimension, such as $B2 or B$2.

For a five-subject marks sheet, let B2:F2 hold subject marks, G2 the obtained total, H2 the percentage and J2 the fictional total possible marks 500. Use =SUM(B2:F2) in G2 and =G2/$J$2*100 in H2 if H2 is displayed as a plain percentage number. Alternatively use =G2/$J$2 with Percentage formatting; do not multiply by 100 and then also apply percentage scaling unintentionally.

Copy down and inspect the next row: B2:F2 should become B3:F3, while $J$2 stays fixed. Mixed references are useful in two-dimensional calculations where one heading row or column must remain fixed. A correct first row is not proof that every copied formula uses the correct references.`,[]),
t('3.4b','Summary, logical and conditional functions',`SUM adds numeric values; COUNT counts numeric cells in a range; COUNTA counts nonempty cells; COUNTBLANK counts blank cells under its rules. AVERAGE uses the numeric values, while MIN and MAX select extremes. For four cells containing 50, 71, a truly empty cell and the text Pending, SUM is 121, COUNT is 2, COUNTA is 3, COUNTBLANK is 1 and AVERAGE is 60.5. Formula results of empty text can affect blank-count rules differently from truly empty cells, so inspect the actual dataset.

IF chooses between results based on a condition. AND requires all its tested conditions; OR accepts at least one. For fictional age/city data, =AND(B2>=18,C2="Lahore") tests both criteria. Define any exercise grade intervals explicitly; do not present a practice formula as an official board policy.

SUMIF conditionally adds values and COUNTIF counts matches. For categories in B2:B11 and prices in C2:C11, =SUMIF(B2:B11,"Stationery",C2:C11) totals stationery prices. =COUNTIF(B2:B11,"Grocery") counts grocery rows. Check range alignment, exact category spelling and independently expected results.`,[]),
t('3.4c','Text functions and data cleaning',`LEFT, RIGHT and MID select characters from text. Excel MID uses a one-based starting position, so =MID("Pakistan",4,3) returns ist. LEFT with 3 returns Pak and RIGHT with 3 returns tan. Do not silently transfer Python's zero-based indexing to Excel's MID arguments.

TRIM removes excess ordinary spaces according to Excel's rules; it is not a promise to remove every possible Unicode whitespace character. UPPER and LOWER change case in returned text. CONCATENATE combines arguments; =CONCATENATE("Ali"," ","Khan") returns Ali Khan. The & operator is another way to join text in these editions.

Apply a formula in a separate column first, compare source and result and retain the original data until the cleaning rule is verified. Leading zeroes in identifiers and meaningful internal spaces must not be discarded merely to make a table look uniform.`,[]),
t('3.5','Charts, data series and labels',`A chart visualises selected data; it does not correct incorrect data. Identify category labels and numeric series before choosing the chart. A line chart can compare ordered observations or two series across common categories, while a column chart may communicate categorical comparisons more clearly for some tasks.

Select the intended source range, insert a suitable chart, add a meaningful title and axes labels and inspect the legend. Adding Test2 requires updating the source/series selection, not merely typing another legend label. Switch Row/Column changes the interpretation of source categories/series and must be checked against the intended question.

Quick Styles affect appearance. Moving or resizing the object should preserve readable labels; editing a series should change the intended source/value relationship. Use a small independently checked sample and inspect the chart together with its worksheet and printed/PDF output.`,[]),
t('3.6','Recording, running and assigning macros',`A macro automates a sequence of actions. In the authorised blank training workbook, expose Developer through File > Options > Customize Ribbon when needed. Decide whether the recorded actions should use fixed locations or relative movement. The recorder's Use Relative References setting concerns recorded action positions; it is related to coordinate intent but is not the same control as inserting $ signs into a worksheet formula.

Choose a meaningful macro name, a safe non-conflicting shortcut and storage in the intended training workbook, begin recording, perform the limited actions and stop recording. Test on a fresh training sheet and compare the actual result. Saving VBA requires a macro-enabled format such as .xlsm; an ordinary .xlsx does not retain that VBA project. Do not enable untrusted macros to complete a classroom example.

Example recording tasks include entering a list of fruit/city names, setting a worksheet font/size, applying a date format and creating a blank fictional Detailed Marks Certificate. A DMC recording can create a title, learner/subject headings, total formula and percentage formula. Keep live personal data out of the example. Assign the recorded macro to an appropriate control or shape using its Assign Macro command, then test the intended target location.

The syllabus's shortcut examples are not universal defaults. Avoid assigning a shortcut that replaces a familiar command without explaining it. Native Excel execution is needed to assess the recorded macro; a stored formula string or a PDF screenshot alone does not prove that VBA ran.`,[])
],short:[['Workbook versus worksheet?','A workbook is the file containing sheets; a worksheet is one cell grid inside it.'],['Clear versus delete?','Clearing removes selected contents without necessarily shifting cells. Deleting can remove cells/rows/columns and shift structure or references.'],['Relative versus absolute reference?','A relative reference adjusts during copying; an absolute reference locks the specified row and column using $.'],['COUNT versus COUNTA?','COUNT counts numeric cells in the referenced range; COUNTA counts nonempty cells, including text.'],['What does SUMIF do?','It adds values satisfying a specified criterion, using properly aligned criterion and sum ranges.'],['Why save recorded VBA in .xlsm?','A macro-enabled workbook format retains the VBA project; an ordinary .xlsx does not preserve it.']],long:[['Design and verify a marks workbook.','Use fictional learner records and five subject columns. Define the total possible marks, calculate each obtained total using SUM and compute percentages with an appropriate fixed denominator. Copy formulas down and inspect both adjusted and locked references. State exercise grade thresholds, test boundary values and compare several rows with independent calculations. Format values deliberately, choose the intended print scope and inspect an exported PDF. A formatted percentage and multiplying by 100 are different operations that should not be accidentally combined twice.'],['Explain a conditional-summary and text-cleaning task.','Define a category/price table and independently expected totals/counts. Use SUMIF to add the intended category prices and COUNTIF to count matching rows, ensuring aligned ranges. Demonstrate COUNT, COUNTA and COUNTBLANK on a small mixed dataset with an actual blank. In a separate text-cleaning column, test LEFT/RIGHT/MID, TRIM, case conversion and joining, keeping original identifiers available. Check exact category spelling, leading zeroes and the difference between Excel MID positioning and Python indexing.'],['Describe a controlled macro-recording exercise.','Start in a blank authorised practice workbook, expose Developer and choose fixed or relative recorded actions according to the task. Name and record a small sequence, stop recording and save the VBA in a suitable macro-enabled format. Test on a fresh practice target, inspect the result and document any shortcut/control assignment. A list-entry or blank DMC task should use fictional content and checked formulas. Do not enable unrelated downloaded macros, and do not claim that native execution occurred merely because a file contains formula text.']],labs:[
lab('excel-entry','Build and organise a practice workbook',['Identify the Name Box, formula bar, active cell, headings, Ribbon and sheet tabs.','Create and name three practice sheets explicitly, enter fictional data, save and reopen the workbook and export a checked PDF.','Compare clearing a cell with deleting a cell/row/column, then test cut/copy/paste and Format Painter on disposable data.','Add/rename sheets, use the fill handle, test a title-area merge and add a header/footer.'],'A saved workbook with clearly explained structural and display operations.',{practicals:[21,22,23,24,25,26]}),
lab('excel-print','Compare three print scopes',['Select a small sample range and preview Print Selection.','Preview the active sheet and the entire workbook.','Record page counts/orientation/scaling and inspect the requested output.'],'Evidence of three distinct print scopes.',{practicals:[27]}),
lab('excel-references','Trace formulas and copied references',['Compare =2+3*4 with =(2+3)*4 and inspect Show Formulas.','Create the B:F marks, G total, H percentage and J2 total-possible example from the notes.','Copy formulas and inspect relative, absolute and mixed references in several destinations.'],'Correct independent results and reference movement.',{practicals:[28,29,30]}),
lab('excel-functions','Check summary, logic and conditional totals',['Use 50, 71, a truly blank cell and Pending to verify the six stated summary results.','Create ten fictional age/city records and test the defined AND condition.','Create ten fictional five-subject marks records, totals, percentages and clearly stated practice grades.','Create ten category/price records; independently check SUMIF stationery total and COUNTIF grocery count.','Apply the text functions to sample strings in a separate result column.'],'A dataset with independently expected summaries, classifications and text results.',{practicals:[31,32,33,34,35,36,37]}),
lab('excel-charts','Compare two test series',['Create a small fictional class/Test1 table and a suitable labelled chart.','Add Test2 to the data and update the series selection.','Inspect axes, legend, title, style and row/column interpretation.'],'A chart whose visible series match the intended source table.',{practicals:[38,39]}),
lab('excel-macros','Record and test four limited macro actions',['Expose Developer in a blank training workbook and compare fixed versus relative recording.','Record, stop, save as .xlsm and run a small list-entry task on a fresh sheet.','Record a font/size and date-format task and inspect the changed target cells.','Record a blank fictional DMC with checked total/percentage formulas; choose a non-conflicting shortcut.','Assign the DMC macro to a permitted shape/control and test it on a new training target.'],'A native-Excel demonstration, safe training targets and recorded expected/observed results.',{practicals:[40,41,42,43,44,45]})]
},
{key:'office-4',subject:'Introduction to MS Office',slug:'dit-computer-science',book:'MS Office',module:4,chapter:5,title:'Microsoft PowerPoint',legacyNoteId:'dit-ms-office-chapter-3-powerpoint-mcq-notes',pages:'13-14,17',reuseMcqs:20,sources:[...source('PowerPoint'),['Zoom feature and edition support','https://support.microsoft.com/en-us/powerpoint/use-zoom-for-powerpoint-to-bring-your-presentation-to-life']],topics:[
t('4.1','Presentation interface and planning',`A presentation is a sequence of slides that supports an audience-facing explanation. The title bar, Quick Access Toolbar, Ribbon/tabs and dialog launchers follow the common Office pattern. The Slides pane shows slide order, the main work area edits the selected slide and the status/view controls support inspection and delivery.

Plan the audience, learning point and slide sequence before adding effects. Use a suitable title slide and content layouts; placeholders preserve a consistent structure. A slide is not a printed essay page. Choose readable type, concise wording and relevant visuals, then check the actual projected/printed output.`,[]),
t('4.2','Create, arrange, save and print slides',`Create a blank presentation or a suitable template and replace sample content. Add new slides with appropriate layouts, duplicate a slide where reuse is meaningful, reorder slides to improve the explanation and delete unnecessary ones. Duplication copies existing content; it does not automatically update facts for the new context.

Save the editable .pptx, close and reopen it and verify the slide sequence. Preview the requested output type: full-page slides, notes pages or handouts are different layouts. For the two-slides handout task, choose that handout setting and inspect page count and readability. Exported PDF delivery and an interactive slideshow have different capabilities.`,[]),
t('4.3','Text, lists and object formatting',`Use placeholders or text boxes to place content. Font size/colour, Format Painter, bullets and numbered lists affect readability and structure. Text-box fill, border, texture and pattern fills change the object appearance; they do not improve incorrect wording or guarantee contrast.

Use a consistent visual hierarchy, align related objects and avoid crowding. Spell-check is a support tool and may not understand names or specialist terminology. Inspect the entire slide at delivery scale after editing, including the longest line and any mixed-script content.`,[]),
t('4.4','Tables, charts and Excel worksheet objects',`A slide table presents structured values; a chart emphasises relationships in data. Insert the intended table and apply readable styling, or create a chart using a checked sample dataset. Resize and move it without clipping labels. A legend must describe the actual series, not a label typed independently of the data.

An inserted Excel worksheet can be embedded or linked depending on the chosen operation. Embedded data reside within the presentation object context, while a link can depend on an external source path. Retain required source assets and test the delivered copy on the intended environment. A chart image is not the same as an editable linked data object.`,[]),
t('4.5','Transitions, animation, motion paths and delivery',`A transition is the effect when moving between slides. Animation affects an object on a slide, such as entrance, emphasis, exit or a motion path. Use start options, sequence, duration and delay deliberately; excessive effects can obscure the lesson. Preview the actual slideshow, not only the edit view.

Presenter View can show speaker tools such as notes and upcoming content in a suitable display configuration. Check which screen the audience sees before delivery. Slideshow setup also controls practical presentation options and navigation.

The syllabus mentions interactive Zoom. Feature availability depends on edition: perpetual PowerPoint 2016 does not offer the same Zoom-creation workflow as supported later editions/Microsoft 365, and its playback can treat Zoom objects as hyperlinks without the zoom transition. In a 2016-only lab, demonstrate an interactive summary with ordinary hyperlinks/action links, and explain the edition distinction instead of inventing a missing Insert > Zoom command.`,[])
],short:[['Transition versus animation?','A transition acts between slides; an animation acts on an object within a slide.'],['What is a slide layout?','A predefined arrangement of placeholders that supports consistent content placement.'],['Why inspect handout preview?','Handout slide count per page and readability differ from full-page slide printing.'],['Embedded versus linked data?','Embedded data are included in the object/file context; a linked object can depend on an external source and path.'],['What must be checked with Presenter View?','The speaker and audience display assignment, notes visibility and actual delivery behaviour.'],['Why discuss PowerPoint Zoom editions?','The syllabus feature is not identically available in every 2016/later product; a suitable 2016 alternative uses ordinary navigation links.']],long:[['Prepare and verify an educational presentation.','State the audience and learning objective, choose suitable title/content layouts and organise a short slide sequence. Add concise checked text and relevant tables/charts, use consistent formatting and retain required data/media sources. Add only effects that support the explanation, test start/timing and inspect the slideshow. Save/reopen the .pptx and inspect any required two-slide handout/PDF. Test Presenter View and audience screens in the actual delivery arrangement.'],['Explain a chart and embedded-data workflow.','Begin with independently checked fictional data and decide what comparison the chart should communicate. Insert the data/chart or an appropriate embedded/linked Excel object, identify actual series/labels and adjust size without clipping. Retain linked sources where required and test a delivered copy after reopening. A chart image, embedded worksheet and externally linked object have different editability and dependencies, so the report should identify the chosen method.'],['Explain interactive delivery and edition limits.','Use meaningful slide order, ordinary links/actions or supported Zoom features to let the presenter navigate. Specify the actual product edition before giving menu instructions. A 2016-only environment can demonstrate a summary slide with hyperlinks; it should not be claimed to create every newer Zoom transition. Test navigation, animation sequencing, slide transitions and the audience display. A PDF export has different interaction capabilities from an editable slideshow.']],labs:[lab('ppt-create','Build and reorder a short presentation',['Create a blank presentation and save a meaningful .pptx.','Use a title slide and content layouts; insert, duplicate, reorder and delete disposable slides.','Close/reopen and confirm the intended sequence.'],'A saved coherent slide deck.',{practicals:[46,47]}),lab('ppt-print','Prepare a two-slide handout',['Open print preview and compare full-page slides with handout layouts.','Select two slides per handout page and inspect the expected pages.'],'A readable requested handout layout.',{practicals:[48]}),lab('ppt-data','Add formatted text, a table and a chart',['Use an available approved template or a blank equivalent; do not depend on a missing online template.','Format text boxes with suitable fills/borders and inspect contrast.','Insert a checked table and chart, then resize/move and inspect labels.'],'Readable text and a chart matching the actual table.',{practicals:[49]}),lab('ppt-deliver','Test effects and navigation',['Apply restrained transitions and object animations, including a permitted motion path.','Set start/timing, preview the slideshow and inspect the audience/Presenter View assignment.','Use edition-supported Zoom or an explicitly labelled hyperlink-summary alternative.'],'A delivery test with documented edition and navigation behaviour.',{practicals:[50]})]
},
{key:'office-5',subject:'Introduction to MS Office',slug:'dit-computer-science',book:'MS Office',module:5,chapter:12,title:'Microsoft Access',legacyNoteId:'dit-nov11-access-mcq-notes',pages:'14,17',reuseMcqs:20,sources:source('Access'),topics:[
t('5.1','Database files and objects',`A relational database organises related facts into tables, with keys and defined relationships supporting consistent data. Access supplies tables, queries, forms and reports within a desktop database application. It is not simply a Word table with a different border.

Create a blank practice database or an available approved template, select a new authorised filename and explore the object navigation pane. An ordinary Access desktop database commonly uses .accdb. Template availability depends on the environment; the task can be demonstrated with an equivalent fictional schema rather than requiring one missing online template.

Distinguish saving object design from record updates. A bound form or datasheet can write record changes as navigation proceeds, so work only with disposable fictional records until the behaviour is understood. Keep a backup before structural changes.`,[]),
t('5.2','Tables, types, keys and relationships',`A field is a named attribute; a record is one row. Choose data types according to meaning: Short Text for a name/identifier that is not a quantity, Number for suitable numeric data, Date/Time for appropriate dates and AutoNumber for an automatically generated key where that design is intended. A phone number is normally an identifier, not an arithmetic amount.

A primary key uniquely identifies a record and cannot be null. A foreign-key field refers to a related table's key. For a simple design, Students has StudentID and FullName; Results has ResultID, StudentID and Marks. One student can have several result records. Match compatible key-field types, such as a Long Integer foreign key for an ordinary AutoNumber identifier.

Referential integrity can prevent an orphan result that refers to a nonexistent student. Configure related tables through the relationship tools and test both an accepted and rejected disposable case. The syllabus's AutoNumber-to-Number exercise should be performed on an appropriate empty/training design with explicit unique values; it is not a recommendation to alter a populated live key casually.

Datasheet View supports row-oriented data work; Design View exposes field definitions and properties. Renaming Field1/Field2 to meaningful attributes improves clarity but does not by itself validate existing values.`,[]),
t('5.3','Forms, sorting and filtering',`A form supplies a user-facing view for entering or reviewing data. Create a simple form from a selected table/query, use the Form Wizard where appropriate or use Design View to place and size controls. Labels describe controls; bound text controls display or edit fields in the selected record source.

Sort changes the displayed order; filter restricts the displayed matching set. Filtering does not delete all nonmatching records. Test navigation, required fields and appropriate input in the training data, and inspect whether a bound edit updates a record as intended.

Layout/Design operations adjust presentation and control properties. They should not be confused with changing every underlying record. Save the intended object design, reopen it and verify that the form's record source and visible labels match the requirement.`,[]),
t('5.4','Reports and printed evidence',`A report formats selected records for presentation or printing. A simple report or Report Wizard can provide an initial structure; Design/Layout tools allow headings, groups, positions and formatting to be refined. A report is not a guarantee that the underlying query is correct.

Inspect Print Preview for page breaks, clipped fields, grouping, totals and page numbering where required. Use a small known result set to compare the record count and values. Save/reopen the report and inspect the actual output layout. A form is oriented toward interaction; a report is oriented toward a formatted presentation of results, although application features can overlap.`,[]),
t('5.5','Queries, joins and criteria',`A select query chooses fields and records from one or more tables. Design View exposes table/field choices and criteria; SQL View expresses the query text. Criteria such as Marks >= 71 restrict results. AND requires combined conditions, while OR permits alternatives; parentheses clarify intended grouping.

Join related tables on the intended key relationship rather than combining every row indiscriminately. For the fictional Students/Results design, the query below returns qualifying name/mark pairs:

~~~sql
SELECT Students.FullName, Results.Marks
FROM Students INNER JOIN Results
ON Students.StudentID = Results.StudentID
WHERE Results.Marks >= 71;
~~~

With Ali at 50 and Ayesha at 80, the expected qualifying row is Ayesha, 80. Re-run a saved query after adding an appropriate disposable record and compare the new result. A select query is different from an action query that changes data. Introductory query practice should not use unreviewed update/delete operations on real records.`,[])
],short:[['Field versus record?','A field is an attribute/column; a record is one row of related values.'],['Primary versus foreign key?','A primary key uniquely identifies its own table record. A foreign key links a record to a related key in another table.'],['What does referential integrity help prevent?','An invalid relationship such as a result referring to a student that does not exist, under the configured rules.'],['Sort versus filter?','Sorting changes order; filtering selects displayed matches and does not inherently delete the other records.'],['Form versus report?','A form supports interactive record work; a report formats selected data for presentation/printing.'],['Why verify a join?','An incorrect relationship can duplicate, omit or mismatch records even when the query executes.']],long:[['Design a small fictional student-results database.','Create Students with an appropriate primary key and learner fields, and Results with its own key, a compatible StudentID foreign key and marks. Use fictional records and suitable data types, then configure the one-to-many relationship and referential integrity. Test a valid result and a reference to a missing student. Build a form for controlled entry, a select query for a stated mark criterion and a report based on that checked result. Save/reopen object designs and compare expected record counts.'],['Explain a query-to-report workflow.','State the information required, select the correct fields and join tables on their intended keys. Apply clearly grouped criteria and compare a small independently known result set, such as Ayesha at 80 qualifying for Marks >= 71 while Ali at 50 does not. Save and rerun after a disposable data addition. Build a report from the verified source and inspect grouping, totals, clipping and page breaks in Print Preview. Execution and attractive formatting do not prove that the underlying join/criteria are correct.'],['Explain controlled table and form editing.','Work in a new disposable training database, choose meaningful fields/types and define keys before relying on relationships. Distinguish Datasheet View data from Design View structure. A bound form can save record changes during navigation, so test the actual write behaviour and retain backups before schema changes. Use Sort/Filter to alter presentation without assuming nonmatching records were deleted. Changing an existing AutoNumber key to Number is a controlled exercise requiring compatible unique values and relationships, not a routine change to a live database.']],labs:[lab('access-create','Create and inspect a training database',['Create a blank database or an available approved student template with a new filename.','Identify tables, forms, queries and reports in the navigation pane.','Add ten fictional records; inspect Datasheet and Design views and assign suitable field names/types.'],'A saved fictional database with explained object roles.',{practicals:[51,52]}),lab('access-relations','Create and test related tables',['Create Students and Results with compatible primary/foreign-key fields.','Define the one-to-many relationship and intended integrity rules.','Test a valid related record and an invalid missing-student reference using disposable data.'],'A relationship diagram and accepted/rejected case evidence.',{practicals:[53]}),lab('access-forms','Build two form designs',['Create a simple form and a wizard-based form on appropriate record sources.','Create a separate design-view form with bound fields and readable labels/dimensions.','Test sorting, filtering, navigation and the actual record-update behaviour.'],'Saved forms with verified source and input behaviour.',{practicals:[54,55]}),lab('access-query','Run and check select queries',['Use a simple query/wizard and compare expected records.','Add criteria in Design View and demonstrate correctly grouped AND/OR conditions.','Join Students and Results on StudentID and compare the provided >=71 sample.'],'A checked single-table and related-table query result.',{practicals:[56,57,58]}),lab('access-report','Produce two report layouts',['Build a simple/wizard report from a verified source.','Inspect Print Preview and adjust layout for readable fields.','Create an equivalent Design View report and compare count and values.'],'Readable reports matching the checked query/table results.',{practicals:[59,60]})]
}
];
